from .objects.integrity_objects import IntegrityCoreObjects
from interops.libraries.squish_actions import common
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def enter_username(username: str) -> None:
    """Locates the Username text box within the Logon pane > types in the given Username string.

    :param str username: Username to be entered into the Username textbox
    """
    common.type_in_textfield(IntegrityCoreObjects.logOnBox_Username_TextBox, username)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def enter_password(password: str) -> None:
    """Locates the Password text box within the Logon pane > types in the given Password string.

    :param str password: Password to be entered into the Password textbox
    """
    common.type_in_textfield(IntegrityCoreObjects.logOnBox_Password_TextBox, password)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def click_logon_ok_button() -> None:
    """Locates the OK Button within the Logon pane > clicks located object using the primary mouse button.
    """
    common.left_click_object(IntegrityCoreObjects.logOnBox_OK_Button)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def confirm_sucessful_login() -> bool:
    """Waits for the main Integrity Log Off to appear and Returns True if it successfully does.

    :return: True or False
    :rtype: bool
    """
    return True if common.find_object(IntegrityCoreObjects.menuBar_Logoff_Button) is not None else False